SELECT task_id FROM public.agent_runtime_conversation_task_bindings
WHERE  AND target_kind = #{owner.target.kind}
  AND target_id = #{owner.target.id} AND session_id = #{owner.sessionRef.sessionId}

SELECT task_id, expected_revision, selected FROM public.agent_runtime_conversation_task_operations
WHERE  AND target_kind = #{owner.target.kind}
  AND target_id = #{owner.target.id} AND session_id = #{owner.sessionRef.sessionId} AND event_id = #{eventId}

